def transform(grid):
    h, w = len(grid), len(grid[0])
    # In this pattern, tile separators are every 4 rows and 3 columns.
    # Compress each separator mark to its corresponding logical cell.
    rh, cw = 4, 3
    marks = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v not in (0, 5) and (r % rh == 2 or c % cw == 2):
                marks[(r // rh, c // cw)] = v

    if not marks:
        return [[5]]
    r0 = min(r for r, c in marks)
    r1 = max(r for r, c in marks)
    c0 = min(c for r, c in marks)
    c1 = max(c for r, c in marks)
    out = [[5 for _ in range(c1-c0+1)] for _ in range(r1-r0+1)]
    for (r, c), v in marks.items():
        out[r-r0][c-c0] = v
    return out
